CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'user' CHECK (role IN ('user','admin')), status TEXT NOT NULL DEFAULT 'active', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS categories (id SERIAL PRIMARY KEY, name TEXT UNIQUE NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS services (id SERIAL PRIMARY KEY, provider_service_id TEXT UNIQUE NOT NULL, category TEXT NOT NULL, name TEXT NOT NULL, description TEXT DEFAULT '', type TEXT DEFAULT 'default', provider_rate NUMERIC(12,4) NOT NULL DEFAULT 0, selling_rate NUMERIC(12,4) NOT NULL DEFAULT 0, min_quantity INTEGER NOT NULL DEFAULT 1, max_quantity INTEGER NOT NULL DEFAULT 100000, refill_available BOOLEAN DEFAULT false, cancel_available BOOLEAN DEFAULT false, featured BOOLEAN DEFAULT false, status TEXT NOT NULL DEFAULT 'active', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wallets (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, balance NUMERIC(14,2) NOT NULL DEFAULT 0, total_deposited NUMERIC(14,2) NOT NULL DEFAULT 0, total_spent NUMERIC(14,2) NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orders (id BIGSERIAL PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), service_id INTEGER NOT NULL REFERENCES services(id), provider_order_id TEXT, service_name_snapshot TEXT NOT NULL, category_snapshot TEXT NOT NULL, link TEXT NOT NULL, quantity INTEGER NOT NULL, provider_rate NUMERIC(12,4) NOT NULL, selling_rate NUMERIC(12,4) NOT NULL, provider_cost NUMERIC(14,2) NOT NULL, customer_price NUMERIC(14,2) NOT NULL, profit NUMERIC(14,2) NOT NULL, status TEXT NOT NULL DEFAULT 'Pending', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS orders_user_idx ON orders(user_id); CREATE INDEX IF NOT EXISTS orders_status_idx ON orders(status);
CREATE TABLE IF NOT EXISTS wallet_transactions (id BIGSERIAL PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), type TEXT NOT NULL, amount NUMERIC(14,2) NOT NULL, balance_after NUMERIC(14,2) NOT NULL, reference TEXT, note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payments (id BIGSERIAL PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), provider TEXT NOT NULL DEFAULT 'razorpay', provider_payment_id TEXT, amount NUMERIC(14,2) NOT NULL, status TEXT NOT NULL DEFAULT 'created', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS support_tickets (id BIGSERIAL PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), subject TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS support_messages (id BIGSERIAL PRIMARY KEY, ticket_id BIGINT REFERENCES support_tickets(id) ON DELETE CASCADE, user_id UUID REFERENCES users(id), message TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS admin_logs (id BIGSERIAL PRIMARY KEY, admin_id UUID REFERENCES users(id), action TEXT NOT NULL, metadata JSONB DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
